import { Input } from './input';
import { Scene } from './scene';

export class Game {
  scene: Scene;
  input: Input;
  playerPosition: { x: number, y: number };
  playerHidden: boolean;
  gameState: { [key: string]: any };

  constructor() {
    this.scene = new Scene();
    this.input = new Input();
    this.playerPosition = { x: 0, y: 0 };
    this.playerHidden = false;
    this.gameState = {};
  }

  update(dt: number) {
    const move = this.input.getMovement();
    if (move) {
      this.playerPosition.x += move.x * dt;
      this.playerPosition.y += move.y * dt;
    }
    if (this.input.isActionPressed('hide')) {
      this.playerHidden = !this.playerHidden;
    }
  }

  render() {
    this.scene.clear();
    this.scene.drawPlayer(this.playerPosition, this.playerHidden);
  }
}

export function GameLoop(game: Game, dt: number) {
  game.update(dt);
  game.render();
}

export class InputHandler {
  keys: { [key: string]: boolean } = {};
  mouse: { left: boolean, right: boolean, x: number, y: number } = { left: false, right: false, x: 0, y: 0 };

  update() {
    // Update keys and mouse state
  }

  handleKeyDown(event: KeyboardEvent) {
    this.keys[event.key] = true;
  }

  handleKeyUp(event: KeyboardEvent) {
    this.keys[event.key] = false;
  }

  handleMouseDown(event: MouseEvent) {
    if (event.button === 0) this.mouse.left = true;
    if (event.button === 2) this.mouse.right = true;
  }

  handleMouseUp(event: MouseEvent) {
    if (event.button === 0) this.mouse.left = false;
    if (event.button === 2) this.mouse.right = false;
  }

  handleMouseMove(event: MouseEvent) {
    this.mouse.x = event.clientX;
    this.mouse.y = event.clientY;
  }
}

