export function createCanvas(): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 800;
  canvas.height = 600;
  document.body.appendChild(canvas);
  return canvas;
}

export function render(canvas: HTMLCanvasElement, scene: Scene): void {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  for (const entity of scene.entities) {
    ctx.fillStyle = entity.color;
    ctx.fillRect(entity.x, entity.y, entity.width, entity.height);
  }
}

import { Vector3 } from '../math/vector3';

export class Cheese {
  position: Vector3;
  velocity: Vector3;

  constructor(position: Vector3, velocity: Vector3) {
    this.position = position;
    this.velocity = velocity;
  }

  update(delta: number): void {
    this.position.add(this.velocity.scale(delta));
  }
}

import { Vector3 } from '../math/vector3.ts';
import { Scene } from '../scene/scene.ts';
import { Player } from './player.ts';

export class Enemy {
  position: Vector3;
  velocity: Vector3;

  constructor(position: Vector3, velocity: Vector3) {
    this.position = position;
    this.velocity = velocity;
  }

  update(scene: Scene, player: Player, dt: number): void {
    const direction = Vector3.subtract(player.position, this.position);
    direction.normalize();
    this.position.add(Vector3.multiply(direction, this.velocity.length() * dt));
  }
}

