import { addTransaction, getBalance, getHistory } from './ledger';

export function startCli() {
  console.log('Welcome to the Banking Ledger App!');
  while (true) {
    const command = prompt('Enter a command (deposit, withdraw, balance, history, exit): ');
    if (!command) continue;
    handleCommand(command);
  }
}

function handleCommand(command: string) {
  switch (command.trim().toLowerCase()) {
    case 'deposit':
      const amount = parseFloat(prompt('Enter the amount to deposit: ') || '0');
      if (!isNaN(amount)) {
        addTransaction(amount);
        console.log(`Deposited ${amount}.`);
      } else {
        console.log('Invalid amount.');
      }
      break;
    case 'withdraw':
      const withdrawAmount = parseFloat(prompt('Enter the amount to withdraw: ') || '0');
      if (!isNaN(withdrawAmount)) {
        addTransaction(-withdrawAmount);
        console.log(`Withdrew ${withdrawAmount}.`);
      } else {
        console.log('Invalid amount.');
      }
      break;
    case 'balance':
      displayBalance();
      break;
    case 'history':
      console.log('Transaction History:');
      console.log(getHistory().join('\n'));
      break;
    case 'exit':
      console.log('Exiting the app. Goodbye!');
      process.exit(0);
    default:
      console.log('Unknown command. Please try again.');
  }
}

function displayBalance() {
  const balance = getBalance();
  console.log(`Current Balance: $${balance.toFixed(2)}`);
}

