import { addTransaction, getBalance, getHistory } from './ledger';
import { save, load } from './store';
import { printHistory } from './history';

export function run(): void {
  let running = true;
  while (running) {
    const input = prompt('Enter command (deposit, withdraw, balance, history, help, exit): ');
    if (!input) continue;
    const command = parseCommand(input);
    switch (command) {
      case 'deposit':
        const amount = parseFloat(prompt('Enter amount to deposit: ') || '0');
        if (!isNaN(amount)) {
          addTransaction(amount);
          save();
          console.log(`Deposited ${amount}. New balance: ${getBalance()}`);
        } else {
          console.log('Invalid amount.');
        }
        break;
      case 'withdraw':
        const withdrawAmount = parseFloat(prompt('Enter amount to withdraw: ') || '0');
        if (!isNaN(withdrawAmount)) {
          addTransaction(-withdrawAmount);
          save();
          console.log(`Withdrew ${withdrawAmount}. New balance: ${getBalance()}`);
        } else {
          console.log('Invalid amount.');
        }
        break;
      case 'balance':
        console.log(`Current balance: ${getBalance()}`);
        break;
      case 'history':
        printHistory(getHistory());
        break;
      case 'help':
        displayHelp();
        break;
      case 'exit':
        running = false;
        break;
      default:
        console.log('Unknown command. Type "help" for a list of commands.');
    }
  }
}

function parseCommand(input: string): string {
  return input.trim().toLowerCase();
}

function displayHelp(): void {
  console.log('Available commands:');
  console.log('deposit <amount> - Deposit a specified amount');
  console.log('withdraw <amount> - Withdraw a specified amount');
  console.log('balance - Check the current balance');
  console.log('history - View transaction history');
  console.log('help - Display this help message');
  console.log('exit - Exit the application');
}

import { Ledger } from './ledger';

export class History {
  private ledger: Ledger;
  private states: Ledger[] = [];

  constructor(ledger: Ledger) {
    this.ledger = ledger;
  }

  saveState(): void {
    this.states.push(this.ledger.copy());
  }

  revertToState(index: number): void {
    if (index >= 0 && index < this.states.length) {
      this.ledger = this.states[index].copy();
    }
  }

  clearHistory(): void {
    this.states = [];
  }
}

export class Ledger {
  private accounts: Account[] = [];

  addAccount(account: Account): void {
    this.accounts.push(account);
  }

  getAccount(id: string): Account | undefined {
    return this.accounts.find(a => a.id === id);
  }

  deposit(accountId: string, amount: number): void {
    const account = this.getAccount(accountId);
    if (account) {
      account.balance += amount;
    }
  }

  withdraw(accountId: string, amount: number): void {
    const account = this.getAccount(accountId);
    if (account && account.balance >= amount) {
      account.balance -= amount;
    }
  }

  showBalance(accountId: string): number {
    const account = this.getAccount(accountId);
    return account ? account.balance : 0;
  }
}

export class Account {
  id: string;
  balance: number;

  constructor(id: string, balance: number = 0) {
