import { Expense, Friend, Balance } from './types';

export function splitExpense(amount: number, friends: Friend[]): { [key: string]: number } {
  const result: { [key: string]: number } = {};
  const numFriends = friends.length;
  if (numFriends === 0) return result;

  const splitAmount = amount / numFriends;
  for (const friend of friends) {
    result[friend.name] = splitAmount;
  }
  return result;
}

export function calculateBalances(expenses: Expense[]): Balance[] {
  const balances: { [key: string]: number } = {};
  for (const expense of expenses) {
    const split = splitExpense(expense.amount, expense.friends);
    for (const friend in split) {
      balances[friend] = (balances[friend] || 0) + split[friend];
    }
  }
  return Object.keys(balances).map(friend => ({ name: friend, balance: balances[friend] }));
}

export function parseExpense(input: string): { date: string; description: string; amount: number } {
  const parts = input.split(',');
  if (parts.length !== 3) {
    throw new Error('Invalid expense format');
  }
  const date = parts[0].trim();
  const description = parts[1].trim();
  const amount = parseFloat(parts[2].trim());
  if (isNaN(amount)) {
    throw new Error('Invalid amount');
  }
  return { date, description, amount };
}

