export function runCli() {
  const storage = loadStorage();
  let deck = loadDeck(storage);

  while (true) {
    console.log('Flashcard Study App');
    console.log('1. Review cards');
    console.log('2. Add card');
    console.log('3. Exit');
    const choice = prompt('Choose an option: ');

    if (choice === '1') {
      deck = reviewCard(deck);
      saveDeck(storage, deck);
    } else if (choice === '2') {
      const question = prompt('Enter the question: ');
      const answer = prompt('Enter the answer: ');
      deck = addCard(deck, question, answer);
      saveDeck(storage, deck);
    } else if (choice === '3') {
      saveStorage(storage);
      break;
    } else {
      console.log('Invalid choice. Please try again.');
    }
  }
}

