import { Router, Request, Response } from 'express';
import { Note, notes } from './types';

const notesRouter = Router();

notesRouter.get('/notes', (req: Request, res: Response) => {
  res.json(notes);
});

notesRouter.get('/notes/:id', (req: Request, res: Response) => {
  const id = parseInt(req.params.id, 10);
  const note = notes.find(n => n.id === id);
  if (note) {
    res.json(note);
  } else {
    res.status(404).send('Note not found');
  }
});

notesRouter.post('/notes', (req: Request, res: Response) => {
  const { title, content } = req.body;
  const newNote: Note = { id: Date.now(), title, content };
  notes.push(newNote);
  res.status(201).json(newNote);
});

notesRouter.put('/notes/:id', (req: Request, res: Response) => {
  const id = parseInt(req.params.id, 10);
  const { title, content } = req.body;
  const noteIndex = notes.findIndex(n => n.id === id);
  if (noteIndex !== -1) {
    notes[noteIndex] = { id, title, content };
    res.json(notes[noteIndex]);
  } else {
    res.status(404).send('Note not found');
  }
});

notesRouter.delete('/notes/:id', (req: Request, res: Response) => {
  const id = parseInt(req.params.id, 10);
  const noteIndex = notes.findIndex(n => n.id === id);
  if (noteIndex !== -1) {
    notes.splice(noteIndex, 1);
    res.status(204).send();
  } else {
    res.status(404).send('Note not found');
  }
});

