export class NoteRepository {
  private notes: { id: number; title: string; content: string }[] = [];

  constructor() {
    this.notes = [];
  }

  async createNote(title: string, content: string): Promise<number> {
    const id = this.notes.length + 1;
    this.notes.push({ id, title, content });
    return id;
  }

  async getNotes(): Promise<{ id: number; title: string; content: string }[]> {
    return this.notes;
  }

  async getNoteById(id: number): Promise<{ id: number; title: string; content: string } | null> {
    return this.notes.find(n => n.id === id) || null;
  }

  async updateNote(id: number, title: string, content: string): Promise<boolean> {
    const note = this.notes.find(n => n.id === id);
    if (note) {
      note.title = title;
      note.content = content;
      return true;
    }
    return false;
  }

  async deleteNote(id: number): Promise<boolean> {
    const index = this.notes.findIndex(n => n.id === id);
    if (index !== -1) {
      this.notes.splice(index, 1);
      return true;
    }
    return false;
  }
}

export class NoteService {
  private noteRepository: NoteRepository;

  constructor(noteRepository: NoteRepository) {
    this.noteRepository = noteRepository;
