import { Database } from 'sqlite3';

let db: Database | null = null;

export function initDatabase(): void {
  db = new Database(':memory:');
  db.serialize(() => {
    db?.run('CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT)');
  });
}

export function saveNote(title: string, content: string): void {
  if (!db) return;
  db.run('INSERT INTO notes (title, content) VALUES (?, ?)', [title, content]);
}

export function loadNotes(): { id: number, title: string, content: string }[] {
  if (!db) return [];
  const notes: { id: number, title: string, content: string }[] = [];
  db.all('SELECT id, title, content FROM notes', (err, rows) => {
    if (err) return;
    rows.forEach(row => notes.push(row));
  });
  return notes;
}

export function deleteNoteById(id: number): void {
  if (!db) return;
  db.run('DELETE FROM notes WHERE id = ?', [id]);
}

