import { Request, Response } from 'express';
import { Note, createNote, deleteNote, getNoteById, getNotes, updateNote } from '../notes';

export const notesController = {
  getAllNotes: (req: Request, res: Response) => {
    const notes = getNotes();
    res.json(notes);
  },
  getNoteById: (req: Request, res: Response) => {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    const note = getNoteById(id);
    if (!note) {
      return res.status(404).json({ error: 'Note not found' });
    }
    res.json(note);
  },
  createNote: (req: Request, res: Response) => {
    const { title, content } = req.body;
    if (!title || !content) {
      return res.status(400).json({ error: 'Title and content are required' });
    }
    const note = createNote(title, content);
    res.status(201).json(note);
  },
  updateNote: (req: Request, res: Response) => {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    const { title, content } = req.body;
    if (!title && !content) {
      return res.status(400).json({ error: 'Title or content is required' });
    }
    const note = updateNote(id, title, content);
    if (!note) {
      return res.status(404).json({ error: 'Note not found' });
    }
    res.json(note);
  },
  deleteNote: (req: Request, res: Response) => {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    const success = deleteNote(id);
    if (!success) {
      return res.status(404).json({ error: 'Note not found' });
    }
    res.status(204).send();
  },
};

export interface Note {
  id: number;
  title: string;
  content: string;
}

export class NotesService {
  private notes: Note[] = [];

  createNote(title: string, content: string): Note {
    const id = this.notes.length > 0 ? this.notes[this.notes.length - 1].id + 1 : 1;
    const note: Note = { id, title, content };
    this.notes.push(note);
    return note;
  }

  getNotes(): Note[] {
    return this.notes;
  }

  updateNote(id: number, title: string, content: string): Note | null {
    const note = this.notes.find(n => n.id === id);
    if (note) {
      note.title = title;
      note.content = content;
    }
    return note || null;
  }

  deleteNote(id: number): void {
    this.notes = this.notes.filter(n => n.id !== id);
  }
}

export function createNote(title: string, content: string): Note {
  return new NotesService().createNote(title, content);
}

export function getNotes(): Note[] {
  return new NotesService().getNotes();
}

export function updateNote(id: number, title: string, content: string): Note | null {
  return new NotesService().updateNote(id, title, content);
}

export function deleteNote(id: number): void {
  new NotesService().deleteNote(id);
}

