export function analyzeLog(logContent: string): string {
  const logLines = parseLog(logContent);
  const levelCounts = countLevels(logLines);
  return reportTopModules(levelCounts);
}

export function countLevels(logEntries: { level: string }[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const entry of logEntries) {
    counts[entry.level] = (counts[entry.level] || 0) + 1;
  }
  return counts;
}

export interface ParsedLog {
  level: string;
  message: string;
}

export const LOG_LEVELS = ['INFO', 'WARN', 'ERROR', 'DEBUG'];

export function parseLog(logLine: string): ParsedLog {
  const parts = logLine.split(': ');
  if (parts.length !== 2) {
    throw new Error('Invalid log line format');
  }
  const level = parts[0].trim();
  const message = parts[1].trim();
  if (!LOG_LEVELS.includes(level)) {
    throw new Error(`Invalid log level: ${level}`);
  }
  return { level, message };
}

import { LogEntry, LogLevel } from './types';

export function parseLog(log: string): LogEntry[] {
  const lines = log.trim().split('\n');
  const entries: LogEntry[] = [];

  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length !== 3) continue;

    const level = parts[0].trim() as LogLevel;
    const module = parts[1].trim();
    const message = parts[2].trim();

    entries.push({ level, module, message });
  }

  return entries;
}

export function countLevels(entries: LogEntry[]): Record<LogLevel, number> {
  const counts: Record<LogLevel, number> = { info: 0, warning: 0, error: 0 };

  for (const entry of entries) {
    counts[entry.level] += 1;
  }

  return counts;
}

function getTopModulesByErrorCount(entries: LogEntry[], count: number): string[] {
  const moduleCounts: Record<string, number> = {};

  for (const entry of entries) {
    if (entry.level === 'error') {
      moduleCounts[entry.module] = (moduleCounts[entry.module] || 0) + 1;
    }
  }

  return Object.entries(moduleCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, count)
    .map(([module]) => module);
}

