import { Transaction, Holding } from './types';

export class Portfolio {
  private transactions: Transaction[];

  constructor() {
    this.transactions = [];
  }

  addTransaction(transaction: Transaction): void {
    this.transactions.push(transaction);
  }

  getHoldings(): Holding[] {
    const holdings: Holding[] = [];
    for (const transaction of this.transactions) {
      const holding = holdings.find(h => h.symbol === transaction.symbol);
      if (holding) {
        holding.quantity += transaction.quantity;
        holding.costBasis += transaction.quantity * transaction.price;
      } else {
        holdings.push({ symbol: transaction.symbol, quantity: transaction.quantity, costBasis: transaction.quantity * transaction.price });
      }
    }
    return holdings;
  }

  getProfitLoss(): number {
    let profitLoss = 0;
    for (const transaction of this.transactions) {
      profitLoss += transaction.quantity * transaction.price;
    }
    return profitLoss;
  }
}

