export function processCommand(command: string, player: Player, rooms: Map<string, Room>): string {
  const parts = command.trim().split(' ');
  const cmd = parts[0].toLowerCase();

  switch (cmd) {
    case 'take':
      return take(parts.slice(1).join(' '), player, rooms);
    case 'move':
      return move(parts.slice(1).join(' '), player, rooms);
    case 'look':
      return look(player, rooms);
    default:
      return 'Unknown command. Try "take", "move", or "look".';
  }
}

function take(itemName: string, player: Player, rooms: Map<string, Room>): string {
  const currentRoom = rooms.get(player.location);
  if (!currentRoom) return 'You are in an unknown room.';
  const item = currentRoom.items.find(i => i.name === itemName);
  if (!item) return `There is no ${itemName} here.`;
  player.inventory.push(item);
  currentRoom.items = currentRoom.items.filter(i => i !== item);
  return `You picked up the ${itemName}.`;
}

function move(direction: string, player: Player, rooms: Map<string, Room>): string {
  const currentRoom = rooms.get(player.location);
  if (!currentRoom) return 'You are in an unknown room.';
  const nextRoomId = currentRoom.exits[direction];
  if (!nextRoomId) return 'You cannot go that way.';
  player.location = nextRoomId;
  return `You moved ${direction}.`;
}

function look(player: Player, rooms: Map<string, Room>): string {
  const currentRoom = rooms.get(player.location);
  if (!currentRoom) return 'You are in an unknown room.';
  return currentRoom.description;
}

