export function countSentences(text: string): number {
  return text.split(/(?<=[.!?])\s+/).filter(sentence => sentence.length > 0).length;
}

function cleanText(text: string): string {
  return text.replace(/[^\w\s]/g, '').toLowerCase();
}

function splitIntoWords(text: string): string[] {
  return text.split(/\s+/).filter(word => word.length > 0);
}

export interface WordFrequency {
  word: string;
  count: number;
}

export function getMostFrequentWords(text: string, limit: number = 5): WordFrequency[] {
  const words = splitIntoWords(cleanText(text));
  const frequencyMap: { [word: string]: number } = {};
  for (const word of words) {
    frequencyMap[word] = (frequencyMap[word] || 0) + 1;
  }
  const sortedWords = Object.entries(frequencyMap).sort((a, b) => b[1] - a[1]);
  return sortedWords.slice(0, limit).map(([word, count]) => ({ word, count }));
}

