export class Board {
  private cells: string[];

  constructor() {
    this.cells = Array(9).fill('');
  }

  public getCells(): string[] {
    return this.cells;
  }

  public setCell(index: number, mark: string): void {
    if (index < 0 || index >= 9) {
      throw new Error('Invalid cell index');
    }
    if (this.cells[index] !== '') {
      throw new Error('Cell already taken');
    }
    this.cells[index] = mark;
  }

  public checkWin(): string | null {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
      [0, 4, 8], [2, 4, 6]            // Diagonals
    ];

    for (const line of winningLines) {
      const [a, b, c] = line;
      if (this.cells[a] && this.cells[a] === this.cells[b] && this.cells[a] === this.cells[c]) {
        return this.cells[a];
      }
    }

    return null;
  }

  public checkTie(): boolean {
    return this.cells.every(cell => cell !== '');
  }
}

