    }

    this.board.setCell(index, this.currentPlayer);
    const winner = this.checkWinner();
    if (winner) {
      return GameState.Won;
    }

    if (this.board.isFull()) {
      return GameState.Tied;
    }

    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    return GameState.Playing;
  }

  private checkWinner(): string | null {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];

    for (const line of lines) {
      const [a, b, c] = line;
      if (this.board.getGrid()[a] && this.board.getGrid()[a] === this.board.getGrid()[b] && this.board.getGrid()[a] === this.board.getGrid()[c]) {
        return this.board.getGrid()[a];
      }
    }

    return null;
  }
}

