export function minimax(board: Board, depth: number, isMaximizing: boolean): number {
  if (isGameOver(board)) {
    return evaluate(board);
  }

  if (isMaximizing) {
    let bestScore = -Infinity;
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        if (board[i][j] === null) {
          board[i][j] = 'O';
          bestScore = Math.max(bestScore, minimax(board, depth + 1, false));
          board[i][j] = null;
        }
      }
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        if (board[i][j] === null) {
          board[i][j] = 'X';
          bestScore = Math.min(bestScore, minimax(board, depth + 1, true));
          board[i][j] = null;
        }
      }
    }
    return bestScore;
  }
}

export function isGameOver(board: Board): boolean {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] && board[i][0] === board[i][1] && board[i][1] === board[i][2]) {
      return true;
    }
    if (board[0][i] && board[0][i] === board[1][i] && board[1][i] === board[2][i]) {
      return true;
    }
  }
  if (board[0][0] && board[0][0] === board[1][1] && board[1][1] === board[2][2]) {
    return true;
  }
  if (board[0][2] && board[0][2] === board[1][1] && board[1][1] === board[2][0]) {
    return true;
  }
  return false;
}

export function evaluate(board: Board): number {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] && board[i][0] === board[i][1] && board[i][1] === board[i][2]) {
      return board[i][0] === 'O' ? 1 : -1;
    }
    if (board[0][i] && board[0][i] === board[1][i] && board[1][i] === board[2][i]) {
      return board[0][i] === 'O' ? 1 : -1;
    }
  }
  if (board[0][0] && board[0][0] === board[1][1] && board[1][1] === board[2][2]) {
    return board[0][0] === 'O' ? 1 : -1;
  }
  if (board[0][2] && board[0][2] === board[1][1] && board[1][1] === board[2][0]) {
    return board[0][2] === 'O' ? 1 : -1;
  }
  return 0;
}

export function playGame() {
  const X = 'X';
  const O = 'O';
  let currentPlayer = X;
  let board = Array(9).fill(null);

  function initializeBoard() {
    board = Array(9).fill(null);
    currentPlayer = X;
  }

  function handlePlayerMove(index) {
    if (board[index] === null) {
      board[index] = currentPlayer;
      currentPlayer = currentPlayer === X ? O : X;
    }
  }

  function minimax(depth, isMaximizing) {
    const winner = checkWinner();
    if (winner !== null) {
      return winner === X ? 1 : -1;
    }
    if (board.every(cell => cell !== null)) {
      return 0;
    }

    if (isMaximizing) {
      let bestScore = -Infinity;
      for (let i = 0; i < 9; i++) {
        if (board[i] === null) {
          board[i] = X;
          const score = minimax(depth + 1, false);
          board[i] = null;
          bestScore = Math.max(score, bestScore);
        }
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (let i = 0; i < 9; i++) {
        if (board[i] === null) {
          board[i] = O;
          const score = minimax(depth + 1, true);
          board[i] = null;
          bestScore = Math.min(score, bestScore);
        }
      }
      return bestScore;
    }
  }

  function checkWinner() {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];
    for (const line of winningLines) {
      const [a, b, c] = line;
      if (board[a] && board[a] === board[b] && board[a] === board[c]) {
        return board[a];
      }
    }
    return null;
  }

  initializeBoard();
  let gameActive = true;

  function playRound() {
    if (!gameActive) return;

    const availableIndices = board.map((cell, index) => cell === null ? index : null).filter(index => index !== null);
    if (availableIndices.length === 0) {
      console.log('Game is a draw!');
      gameActive = false;
      return;
    }

    const index = availableIndices[Math.floor(Math.random() * availableIndices.length)];
    handlePlayerMove(index);
    const winner = checkWinner();
    if (winner !== null) {
      console.log(`Player ${winner} wins!`);
      gameActive = false;
      return;
    }

    const bestMove = minimax(0, true);
    handlePlayerMove(bestMove);
    const winner2 = checkWinner();
    if (winner2 !== null) {
      console.log(`Player ${winner2} wins!`);
      gameActive = false;
      return;
    }
  }

  for (let i = 0; i < 9; i++) {
    playRound();
  }
}

export class TicTacToeBoard {
