export class MinMaxComputer {
  game: Game;

  constructor(game: Game) {
    this.game = game;
  }

  minimax(board: string[][], depth: number, isMaximizing: boolean): number {
    const winner = this.checkWin(board);
    if (winner === 'X') return 1;
    if (winner === 'O') return -1;
    if (this.checkDraw(board)) return 0;

    if (isMaximizing) {
      let bestScore = -Infinity;
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
          if (board[i][j] === '') {
            board[i][j] = 'X';
            bestScore = Math.max(bestScore, this.minimax(board, depth + 1, !isMaximizing));
            board[i][j] = '';
          }
        }
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
          if (board[i][j] === '') {
            board[i][j] = 'O';
            bestScore = Math.min(bestScore, this.minimax(board, depth + 1, !isMaximizing));
            board[i][j] = '';
          }
        }
      }
      return bestScore;
    }
  }

  checkWin(board: string[][]): string | null {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];
    for (const line of lines) {
      const [a, b, c] = line;
      if (board[a] === board[b] && board[b] === board[c] && board[a] !== '') {
        return board[a];
      }
    }
    return null;
  }

  checkDraw(board: string[][]): boolean {
    return board.every(row => row.every(cell => cell !== ''));
  }

  getBestMove(board: string[][]): { row: number, col: number } {
    let bestScore = -Infinity;
    let bestMove = { row: -1, col: -1 };
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        if (board[i][j] === '') {
          board[i][j] = 'X';
          const score = this.minimax(board, 0, false);
          board[i][j] = '';
          if (score > bestScore) {
            bestScore = score;
            bestMove = { row: i, col: j };
          }
        }
      }
    }
    return bestMove;
  }
}

export interface Board {
  [key: string]: 'X' | 'O' | null;
}

export interface GameState {
  board: Board;
  currentPlayer: 'X' | 'O';
}

export function isGameOver(state: GameState): boolean {
  const winner = getWinner(state);
  return winner !== null || Object.values(state.board).every(cell => cell !== null);
}

export function getWinner(state: GameState): 'X' | 'O' | null {
  const lines = [
    ['0', '1', '2'], ['3', '4', '5'], ['6', '7', '8'],
    ['0', '3', '6'], ['1', '4', '7'], ['2', '5', '8'],
    ['0', '4', '8'], ['2', '4', '6']
  ];
  for (const line of lines) {
    const [a, b, c] = line;
    if (state.board[a] && state.board[a] === state.board[b] && state.board[a] === state.board[c]) {
      return state.board[a];
    }
  }
  return null;
}

export function getAvailableMoves(state: GameState): string[] {
  return Object.keys(state.board).filter(key => state.board[key] === null);
}

export function play(state: GameState, move: string): GameState {
  if (state.board[move] !== null) {
    throw new Error('Invalid move');
  }
  const newBoard = { ...state.board, [move]: state.currentPlayer };
  const currentPlayer = state.currentPlayer === 'X' ? 'O' : 'X';
  return { board: newBoard, currentPlayer };
}

export function minimax(state: GameState, depth: number, isMaximizing: boolean): number {
  const winner = getWinner(state);
  if (winner === 'X') return 1;
  if (winner === 'O') return -1;
  if (Object.values(state.board).every(cell => cell !== null)) return 0;

  if (isMaximizing) {
    let bestScore = -Infinity;
    for (const move of getAvailableMoves(state)) {
      const nextState = play(state, move);
      const score = minimax(nextState, depth + 1, false);
      bestScore = Math.max(bestScore, score);
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (const move of getAvailableMoves(state)) {
      const nextState = play(state, move);
      const score = minimax(nextState, depth + 1, true);
      bestScore = Math.min(bestScore, score);
    }
    return bestScore;
  }
}

export interface GameState {
  board: string[];
  currentPlayer: 'X' | 'O';
}

export function makeMove(state: GameState, index: number): GameState {
  if (state.board[index] !== '') return state;
  const newBoard = [...state.board];
  newBoard[index] = state.currentPlayer;
  return { board: newBoard, currentPlayer: state.currentPlayer === 'X' ? 'O' : 'X' };
}

export function minimax(state: GameState, depth: number, isMaximizing: boolean): number {
  const winner = checkWinner(state.board);
  if (winner !== null) return winner === 'X' ? 1 : -1;
  if (state.board.every(cell => cell !== '')) return 0;

  if (isMaximizing) {
    let bestScore = -Infinity;
    for (let i = 0; i < 9; i++) {
      if (state.board[i] === '') {
        const nextState = makeMove(state, i);
        const score = minimax(nextState, depth + 1, false);
        bestScore = Math.max(bestScore, score);
      }
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (let i = 0; i < 9; i++) {
      if (state.board[i] === '') {
        const nextState = makeMove(state, i);
        const score = minimax(nextState, depth + 1, true);
        bestScore = Math.min(bestScore, score);
      }
    }
    return bestScore;
  }
}

function checkWinner(board: string[]): 'X' | 'O' | null {
  const winningLines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  for (const line of winningLines) {
    const [a, b, c] = line;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return board[a] as 'X' | 'O';
    }
  }
  return null;
}

