export function minimax(board: Player[][], depth: number, isMaximizing: boolean): number {
  const winner = checkWinner(board);
  if (winner === Player.X) return 1;
  if (winner === Player.O) return -1;
  if (isBoardFull(board)) return 0;

  if (isMaximizing) {
    let bestScore = -Infinity;
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        if (board[i][j] === null) {
          board[i][j] = Player.X;
          bestScore = Math.max(bestScore, minimax(board, depth + 1, false));
          board[i][j] = null;
        }
      }
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        if (board[i][j] === null) {
          board[i][j] = Player.O;
          bestScore = Math.min(bestScore, minimax(board, depth + 1, true));
          board[i][j] = null;
        }
      }
    }
    return bestScore;
  }
}

