import * as fs from 'fs';

export function parseCSV(filePath: string): number[] {
  const fileContent = fs.readFileSync(filePath, 'utf-8');
  const lines = fileContent.trim().split('\n');
  const prices: number[] = [];

  for (const line of lines) {
    const values = line.split(',');
    if (values.length > 0) {
      const price = parseFloat(values[0].trim());
      if (!isNaN(price)) {
        prices.push(price);
      }
    }
  }

  return prices;
}

export function calculateMovingAverage(prices: number[]): number[] {
  const movingAverages: number[] = [];
  for (let i = 4; i < prices.length; i++) {
    const sum = prices.slice(i - 4, i + 1).reduce((acc, p) => acc + p, 0);
    movingAverages.push(sum / 5);
  }
  return movingAverages;
}

