import { Poll, PollResults } from './types';
import { savePoll, loadPolls } from './storage';

export class PollService {
  private polls: Poll[] = [];

  constructor() {
    this.polls = loadPolls();
  }

  createPoll(options: string[]): Poll {
    const pollId = Date.now().toString();
    const poll: Poll = { id: pollId, options: options.map(opt => ({ option: opt, votes: 0 })) };
    this.polls.push(poll);
    savePoll(poll);
    return poll;
  }

  castVote(pollId: string, option: string): void {
    const poll = this.polls.find(p => p.id === pollId);
    if (!poll) return;
    const opt = poll.options.find(o => o.option === option);
    if (opt) opt.votes += 1;
    savePoll(poll);
  }

  getResults(pollId: string): PollResults {
    const poll = this.polls.find(p => p.id === pollId);
    if (!poll) return { pollId, results: [] };
    const totalVotes = poll.options.reduce((acc, o) => acc + o.votes, 0);
    return {
      pollId,
      results: poll.options.map(o => ({
        option: o.option,
        votes: o.votes,
        percentage: totalVotes > 0 ? (o.votes / totalVotes) * 100 : 0
      }))
    };
  }
}

import { Poll } from './types';

const POLL_STORAGE_KEY = 'voting-polls';

export function savePoll(poll: Poll): void {
  const polls = loadPolls();
  polls.push(poll);
  localStorage.setItem(POLL_STORAGE_KEY, JSON.stringify(polls));
}

export function loadPolls(): Poll[] {
  const data = localStorage.getItem(POLL_STORAGE_KEY);
  return data ? JSON.parse(data) : [];
}

export interface PollOption {
  id: string;
  text: string;
  votes: number;
}

export interface Poll {
  id: string;
  question: string;
  options: PollOption[];
}

import * as fs from 'fs';
import * as path from 'path';

const EVENTS_FILE_PATH = path.join(__dirname, '../data/events.json');

export function loadEvents(): Event[] {
  try {
    const data = fs.readFileSync(EVENTS_FILE_PATH, 'utf-8');
    return JSON.parse(data) || [];
  } catch (error) {
    console.error('Error loading events:', error);
    return [];
  }
}

export function saveEvents(events: Event[]): void {
  try {
    fs.writeFileSync(EVENTS_FILE_PATH, JSON.stringify(events, null, 2));
  } catch (error) {
    console.error('Error saving events:', error);
  }
}

export type ExpenseItem = {
  id: number;
  date: string;
  category: string;
  amount: number;
};

let expenses: ExpenseItem[] = [];

export function addExpense(expense: ExpenseItem): void {
  expenses.push(expense);
}

import * as fs from 'fs';
import * as path from 'path';

const dataPath = path.join(__dirname, '../data/expenses.json');

export function loadExpenses(): Expense[] {
  try {
    const data = fs.readFileSync(dataPath, 'utf-8');
    return JSON.parse(data) || [];
  } catch (error) {
    return [];
  }
}

export function saveExpenses(expenses: Expense[]): void {
  fs.writeFileSync(dataPath, JSON.stringify(expenses, null, 2));
}

export type ExpenseItem = {
  id: number;
  description: string;
  amount: number;
  category: string;
  date: Date;
};

let expenses: ExpenseItem[] = [];

export function addExpense(description: string, amount: number, category: string, date: Date): void {
  const id = expenses.length > 0 ? expenses[expenses.length - 1].id + 1 : 1;
  expenses.push({ id, description, amount, category, date });
}

export function getMonthlyTotals(): { month: string; total: number }[] {
  const totals: { month: string; total: number }[] = [];
  for (const expense of expenses) {
    const month = expense.date.toISOString().slice(0, 7);
    const existing = totals.find(t => t.month === month);
    if (existing) {
      existing.total += expense.amount;
    } else {
      totals.push({ month, total: expense.amount });
    }
  }
  return totals;
}

export function getCategoryBreakdown(): { category: string; total: number }[] {
  const breakdown: { category: string; total: number }[] = [];
  for (const expense of expenses) {
    const existing = breakdown.find(b => b.category === expense.category);
    if (existing) {
      existing.total += expense.amount;
    } else {
      breakdown.push({ category: expense.category, total: expense.amount });
    }
  }
  return breakdown;
}

export interface Todo {
  id: number;
  description: string;
  completed: boolean;
}

let todos: Todo[] = [];

export function addTodo(todo: Todo): void {
  todos.push(todo);
}

export function listTodos(): Todo[] {
  return todos;
}

export type Todo = {
  id: number;
  title: string;
  description: string;
  completed: boolean;
};

export type TodoList = Todo[];

export type Todo = {
  id: string;
  text: string;
  isDone: boolean;
};

let tasks: Todo[] = [];

export function addTask(taskText: string): void {
  const newTask: Todo = {
    id: Date.now().toString(),
    text: taskText,
    isDone: false,
  };
  tasks.push(newTask);
  saveTasks();
}

export function toggleTaskDone(taskId: string): void {
  tasks = tasks.map(task => task.id === taskId ? { ...task, isDone: !task.isDone } : task);
  saveTasks();
}

export function deleteTask(taskId: string): void {
  tasks = tasks.filter(task => task.id !== taskId);
  saveTasks();
}

export function getTasks(): Todo[] {
  return tasks;
}

function saveTasks(): void {
  localStorage.setItem('tasks', JSON.stringify(tasks));
}

function loadTasks(): void {
  const storedTasks = localStorage.getItem('tasks');
  if (storedTasks) {
    tasks = JSON.parse(storedTasks);
  }
}

loadTasks();

const todoList = document.getElementById('todoList');
const inputField = document.getElementById('inputField');
const addButton = document.getElementById('addButton');

addButton.addEventListener('click', addTodoItem);

function addTodoItem() {
  const todoText = inputField.value.trim();
  if (!todoText) return;
  const li = document.createElement('li');
  const deleteButton = document.createElement('button');
  deleteButton.textContent = 'Delete';
  deleteButton.addEventListener('click', (event) => deleteTodoItem(event));
  li.textContent = todoText;
  li.appendChild(deleteButton);
  todoList.appendChild(li);
  inputField.value = '';
}

function deleteTodoItem(event) {
  const li = event.target.parentElement;
  todoList.removeChild(li);
}
